// F-003 — Lead validation (+ webhook secret check)
const item = $input.first().json;
const headers = Object.fromEntries(
  Object.entries(item.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v])
);
const body = item.body || {};

if (headers['x-webhook-secret'] !== $env.N8N_WEBHOOK_SECRET) {
  return [{ json: { valid: false, status: 401, error: 'invalid webhook secret' } }];
}

const name = String(body.name || '').trim();
const email = String(body.email || '').trim();
const errors = [];
if (!name) errors.push('name is required');
if (!email) errors.push('email is required');
else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email format is invalid');
if (body.phone) {
  const digits = String(body.phone).replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) errors.push('phone format is invalid');
}
if (errors.length) {
  return [{ json: { valid: false, status: 422, error: errors.join('; ') } }];
}

return [{ json: {
  valid: true,
  payload: {
    name,
    email,
    phone: body.phone || null,
    source: body.source || 'test',
    course_interest: body.course_interest || null,
    budget: body.budget || null,
    timeline: body.timeline || null,
    message: body.message || null
  }
} }];

// Prepare the OpenAI request (F-004) and carry run_id + payload through the pipeline
const payload = $('Validate & authorize').first().json.payload;
const raw = $('Log run started').first().json;
const run = Array.isArray(raw) ? raw[0] : raw;

const system = [
  'You are the lead-qualification analyst for a mid-sized education and training company.',
  'You qualify incoming student leads for admissions counselors.',
  'Respond with ONLY a single JSON object with exactly these keys:',
  '{ "score": <integer 0-100, likelihood of conversion>, "category": "HOT"|"WARM"|"COLD", "intent": "HIGH"|"MEDIUM"|"LOW", "course": <string or null>, "timeline": <string or null>, "summary": <one-sentence summary of the lead>, "recommended_action": <concrete next action for the counselor> }'
].join('\n');

const user = [
  'New lead received from ' + (payload.source || 'unknown source') + ':',
  '- name: ' + payload.name,
  '- email: ' + payload.email,
  '- phone: ' + (payload.phone || 'not provided'),
  '- course of interest: ' + (payload.course_interest || 'not specified'),
  '- budget: ' + (payload.budget || 'not specified'),
  '- timeline: ' + (payload.timeline || 'not specified'),
  '- message: ' + (payload.message || '(empty)')
].join('\n');

return [{ json: { run_id: run.id, payload, system, user } }];

// Schema validation — detects truncation (incomplete JSON) separately
// from malformed JSON so the pipeline can retry the former.
const ai = $('AI lead analysis').first().json;
const prep = $('Prepare AI prompt').first().json;
const retryCount = prep._retryCount || 0;

const text = (ai.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
const truncated = !text.trim().endsWith('}') && !text.trim().endsWith(']');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { ok: false, truncated, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, error: 'AI response was not valid JSON' + (truncated ? ' (truncated)' : '') + ': ' + e.message } }];
}

const errors = [];
if (!Number.isInteger(parsed.score) || parsed.score < 0 || parsed.score > 100) errors.push('score must be an integer between 0 and 100');
if (!['HIGH', 'MEDIUM', 'LOW'].includes(parsed.intent)) errors.push('intent must be HIGH, MEDIUM or LOW');
if (typeof parsed.summary !== 'string' || !parsed.summary.trim()) errors.push('summary is required');
if (typeof parsed.recommended_action !== 'string' || !parsed.recommended_action.trim()) errors.push('recommended_action is required');
if (errors.length) {
  return [{ json: { ok: false, truncated: false, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, raw: parsed, error: errors.join('; ') } }];
}

return [{ json: { ok: true, truncated: false, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, analysis: parsed } }];

// F-005 / F-006 — deterministic scoring + classification thresholds.
// The model proposes a score; the thresholds below are the auditable rule
// that decides HOT/WARM/COLD and intent level.
const { run_id, payload, analysis } = $input.first().json;
const score = analysis.score;
const category = score >= 70 ? 'HOT' : score >= 40 ? 'WARM' : 'COLD';
const intent = score >= 70 ? 'HIGH' : score >= 40 ? 'MEDIUM' : 'LOW';
return [{ json: { run_id, payload, analysis: { ...analysis, score, category, intent } } }];

